  "settings.audio.txPower.label": "TX-Leistung",
  "settings.audio.txPower.aria": "Sende-Aussteuerung",
  "settings.audio.txPower.hint": "Die Audio-<b>Aussteuerung</b> ins Funkgerät — dasselbe Stellglied wie der <b>Pwr</b>-Regler im Cockpit (beide laufen jetzt immer gleich). So weit zurücknehmen, bis die ALC des Geräts gerade null zeigt. Das sind <em>nicht</em> die HF-Watt des Geräts — die werden am Funkgerät eingestellt.",
  "settings.audio.rxLevel.label": "RX-Pegel",
  "settings.audio.rxLevel.meter": "RX-Audiopegel",
  "settings.audio.rxLevel.hint": "Eine dB-Skala wie bei WSJT-X — Ziel etwa 30 dB. Alles von ~15–60 dB dekodiert sauber; Rot heißt zu heiß (RX-Verstärkung oder das Audio am Gerät zurücknehmen).",
  "settings.audio.rxGain.label": "RX-Verstärkung",
  "settings.audio.rxGain.aria": "RX-Aufnahmeverstärkung",
