  "settings.js8.freqs.export.failed": "JS8-Frequenzen konnten nicht gespeichert werden",
  "settings.js8.freqs.import.action": "Importieren…",
  "settings.js8.freqs.import.bad": "Diese Datei enthält keine JS8-Frequenzen, die Nexus lesen kann. Nimm eine Datei, die diese Liste exportiert hat.",
  "settings.js8.freqs.import.done": "JS8-Frequenzen importiert: {{count}}. Speichern, um sie zu behalten.",
  "settings.js8.freqs.import.confirm.title": "Deine JS8-Frequenzen ersetzen?",
  "settings.js8.freqs.import.confirm.body": "Deine Liste wird durch die aus dieser Datei ersetzt.",
  "settings.js8.freqs.import.confirm.action": "Ersetzen",
  "settings.js8.schedule.label": "Frequenz nach Zeitplan wechseln",
  "settings.js8.schedule.hint": "Standardmäßig aus, wie in JS8Call. Eingeschaltet wechselt Nexus die Frequenz des Funkgeräts SELBSTSTÄNDIG zu den unten stehenden Zeiten, auch wenn niemand am Gerät ist: erst ein Hinweis, dann 30 Sekunden später der Wechsel, sofern du ihn nicht abbrichst. Nie während des Sendens oder solange eine Nachricht hinausgeht.",
  "settings.js8.schedule.list.label": "Zeitplan (UTC)",
  "settings.js8.schedule.list.hint": "Jede Zeile: eine Frequenz und von wann bis wann (UTC) sie gilt. Am Ende einer Zeile wird nicht zurückgewechselt; dafür eine weitere Zeile anlegen. Überschneiden sich Zeilen, gilt die, die später beginnt.",
  "settings.js8.schedule.empty": "Noch keine Zeilen.",
  "settings.js8.schedule.mhz.aria": "Frequenz von Zeile {{n}} in MHz",
  "settings.js8.schedule.from.aria": "Zeile {{n}}: ab (UTC)",
  "settings.js8.schedule.until.aria": "Zeile {{n}}: bis (UTC)",
  "settings.js8.schedule.until.title": "Zu dieser Zeit wird nicht zurückgewechselt. Für die Rückkehr eine weitere Zeile anlegen.",
