  "phone.sub.rf.aria": "HF-Verstärkung des Unterempfängers",
  "phone.sub.rf.title": "HF-Verstärkung des Unterempfängers — sein eigenes Eingangsteil. Von Nexus gesetzt; das Funkgerät meldet sie nicht zurück.",
  "phone.sub.af.aria": "AF-Lautstärke des Unterempfängers",
